<?php
/**
 * Connection to the AutoBuzy marketplace and signed HTTP client.
 *
 * The connection code (AB1.<base64url JSON>) is generated by marketplace
 * staff. The secret is stored encrypted (libsodium, key derived from this
 * site's salts) and never displayed again.
 *
 * Signature: hex(HMAC-SHA256(secret, ts \n METHOD \n route \n sha256(body))).
 *
 * @package AutomotiveMarketplaceConnector
 */

namespace ACX;

defined( 'ABSPATH' ) || exit;

final class Connection {

	const OPTION = 'acx_connection';
	const REMOTE = 'acx_remote';

	/* ------------------------------------------------------------------ */
	/* Crypto                                                              */
	/* ------------------------------------------------------------------ */

	private static function key() {
		return sodium_crypto_generichash( wp_salt( 'auth' ) . '|acx', '', SODIUM_CRYPTO_SECRETBOX_KEYBYTES );
	}

	private static function encrypt( $plain ) {
		$nonce = random_bytes( SODIUM_CRYPTO_SECRETBOX_NONCEBYTES );
		return base64_encode( $nonce . sodium_crypto_secretbox( $plain, $nonce, self::key() ) );
	}

	private static function decrypt( $stored ) {
		$raw = base64_decode( (string) $stored, true );
		if ( false === $raw || strlen( $raw ) <= SODIUM_CRYPTO_SECRETBOX_NONCEBYTES ) {
			return '';
		}
		$plain = sodium_crypto_secretbox_open( substr( $raw, SODIUM_CRYPTO_SECRETBOX_NONCEBYTES ), substr( $raw, 0, SODIUM_CRYPTO_SECRETBOX_NONCEBYTES ), self::key() );
		return false === $plain ? '' : $plain;
	}

	public static function sign( $secret, $timestamp, $method, $route, $body ) {
		return hash_hmac( 'sha256', $timestamp . "\n" . strtoupper( $method ) . "\n" . $route . "\n" . hash( 'sha256', (string) $body ), $secret );
	}

	/* ------------------------------------------------------------------ */
	/* State                                                               */
	/* ------------------------------------------------------------------ */

	public static function get() {
		$conn = get_option( self::OPTION );
		return is_array( $conn ) && ! empty( $conn['key'] ) ? $conn : null;
	}

	public static function is_connected() {
		$conn = self::get();
		return $conn && ! empty( $conn['connected_at'] );
	}

	public static function key_id() {
		$conn = self::get();
		return $conn ? $conn['key'] : '';
	}

	public static function secret() {
		$conn = self::get();
		return $conn ? self::decrypt( $conn['secret'] ) : '';
	}

	/** Last account info returned by the marketplace (plan, limits…). */
	public static function remote() {
		$remote = get_option( self::REMOTE );
		return is_array( $remote ) ? $remote : array();
	}

	public static function save_remote( array $data ) {
		$keep = array_intersect_key( $data, array_flip( array( 'dealer', 'subscription', 'limits' ) ) );
		if ( $keep ) {
			$keep['checked_at'] = time();
			update_option( self::REMOTE, array_merge( self::remote(), $keep ), false );
		}
	}

	/**
	 * Decode a connection code.
	 *
	 * @return array|\WP_Error { url, key, secret }
	 */
	public static function parse_code( $code ) {
		$code = trim( preg_replace( '/\s+/', '', (string) $code ) );
		if ( 0 !== strpos( $code, 'AB1.' ) ) {
			return new \WP_Error( 'acx_code', __( 'This is not a valid AutoBuzy connection code.', 'automotive-marketplace-connector' ) );
		}
		$json = base64_decode( strtr( substr( $code, 4 ), '-_', '+/' ), true );
		$data = $json ? json_decode( $json, true ) : null;
		if ( ! is_array( $data ) || empty( $data['url'] ) || empty( $data['key'] ) || empty( $data['secret'] ) ) {
			return new \WP_Error( 'acx_code', __( 'This connection code is incomplete. Copy it again from the marketplace.', 'automotive-marketplace-connector' ) );
		}
		$url = esc_url_raw( (string) $data['url'], array( 'https', 'http' ) );
		if ( ! $url || ( 'https' !== wp_parse_url( $url, PHP_URL_SCHEME ) && ! ( defined( 'WP_DEBUG' ) && WP_DEBUG ) ) ) {
			return new \WP_Error( 'acx_code', __( 'The marketplace address must use HTTPS.', 'automotive-marketplace-connector' ) );
		}
		if ( ! preg_match( '/^ab_[a-f0-9]{24}$/', (string) $data['key'] ) || ! preg_match( '/^[a-f0-9]{64}$/', (string) $data['secret'] ) ) {
			return new \WP_Error( 'acx_code', __( 'This connection code is damaged. Copy it again from the marketplace.', 'automotive-marketplace-connector' ) );
		}
		return array(
			'url'    => untrailingslashit( $url ),
			'key'    => (string) $data['key'],
			'secret' => (string) $data['secret'],
		);
	}

	/**
	 * Connect with a code: store it, then perform the handshake.
	 *
	 * @return true|\WP_Error
	 */
	public static function connect( $code ) {
		$data = self::parse_code( $code );
		if ( is_wp_error( $data ) ) {
			return $data;
		}
		$previous = get_option( self::OPTION );
		update_option(
			self::OPTION,
			array(
				'url'          => $data['url'],
				'key'          => $data['key'],
				'secret'       => self::encrypt( $data['secret'] ),
				'connected_at' => 0,
			),
			false
		);
		$result = self::request(
			'POST',
			'/sync/handshake',
			array(
				'site_url'          => home_url( '/' ),
				'connector_version' => ACX_VERSION,
				'crm_version'       => defined( 'ADC_VERSION' ) ? ADC_VERSION : '',
			)
		);
		if ( is_wp_error( $result ) ) {
			// Keep the previous working connection, if any.
			if ( is_array( $previous ) && ! empty( $previous['connected_at'] ) ) {
				update_option( self::OPTION, $previous, false );
			} else {
				delete_option( self::OPTION );
			}
			return $result;
		}
		$conn                 = self::get();
		$conn['connected_at'] = time();
		update_option( self::OPTION, $conn, false );
		self::save_remote( $result );
		Database::log( __( 'Connected to the marketplace.', 'automotive-marketplace-connector' ) );
		return true;
	}

	public static function disconnect() {
		delete_option( self::OPTION );
		delete_option( self::REMOTE );
		Database::log( __( 'Disconnected from the marketplace.', 'automotive-marketplace-connector' ) );
	}

	/**
	 * Signed request to marketplace/v1.
	 *
	 * @param string     $method          HTTP method.
	 * @param string     $path            Path after /marketplace/v1, e.g. /sync/status.
	 * @param array|null $body            JSON body.
	 * @param string     $idempotency_key Optional; generated for writes.
	 * @return array|\WP_Error Decoded JSON (with '_status').
	 */
	public static function request( $method, $path, $body = null, $idempotency_key = '' ) {
		$conn   = self::get();
		$secret = self::secret();
		if ( ! $conn || '' === $secret ) {
			return new \WP_Error( 'acx_not_connected', __( 'This website is not connected to the marketplace.', 'automotive-marketplace-connector' ) );
		}
		$method  = strtoupper( $method );
		$route   = '/marketplace/v1' . $path;
		$payload = null === $body ? '' : wp_json_encode( $body );
		$ts      = time();
		$headers = array(
			'Accept'          => 'application/json',
			'X-AMC-Key'       => $conn['key'],
			'X-AMC-Timestamp' => (string) $ts,
			'X-AMC-Signature' => self::sign( $secret, $ts, $method, $route, $payload ),
		);
		if ( '' !== $payload ) {
			$headers['Content-Type'] = 'application/json';
		}
		if ( 'GET' !== $method ) {
			$headers['Idempotency-Key'] = $idempotency_key ? $idempotency_key : wp_generate_uuid4();
		}
		$response = wp_remote_request(
			$conn['url'] . '/wp-json' . $route,
			array(
				'method'      => $method,
				'timeout'     => 20,
				'redirection' => 0,
				'headers'     => $headers,
				'body'        => '' === $payload ? null : $payload,
			)
		);
		if ( is_wp_error( $response ) ) {
			return new \WP_Error( 'acx_http', sprintf( /* translators: %s: error */ __( 'The marketplace could not be reached: %s', 'automotive-marketplace-connector' ), $response->get_error_message() ) );
		}
		$code = (int) wp_remote_retrieve_response_code( $response );
		$data = json_decode( (string) wp_remote_retrieve_body( $response ), true );
		$data = is_array( $data ) ? $data : array();
		if ( $code >= 400 ) {
			$message = isset( $data['message'] ) ? (string) $data['message'] : 'HTTP ' . $code;
			return new \WP_Error( isset( $data['code'] ) ? (string) $data['code'] : 'acx_http_' . $code, $message, array( 'status' => $code ) );
		}
		$data['_status'] = $code;
		return $data;
	}

	/**
	 * Verify a signed request coming FROM the marketplace (webhooks, AI actions).
	 *
	 * @return true|\WP_Error
	 */
	public static function verify( \WP_REST_Request $request ) {
		$secret    = self::secret();
		$key       = (string) $request->get_header( 'x-amc-key' );
		$timestamp = (int) $request->get_header( 'x-amc-timestamp' );
		$signature = strtolower( (string) $request->get_header( 'x-amc-signature' ) );
		if ( '' === $secret || ! hash_equals( self::key_id(), $key ) ) {
			return new \WP_Error( 'acx_auth', 'Unknown key.', array( 'status' => 401 ) );
		}
		if ( abs( time() - $timestamp ) > 300 ) {
			return new \WP_Error( 'acx_auth', 'Timestamp outside the allowed window.', array( 'status' => 401 ) );
		}
		$expected = self::sign( $secret, $timestamp, $request->get_method(), $request->get_route(), $request->get_body() );
		if ( ! hash_equals( $expected, $signature ) ) {
			return new \WP_Error( 'acx_auth', 'Invalid signature.', array( 'status' => 401 ) );
		}
		return true;
	}
}
